/* All membership, verification, discussion and review data stays in this browser. */
'use strict';
const mentorExamples={
 b1:{school:'새봄대학교 (가상)',department:'시각디자인학과',year:'3학년',concerns:['진로 고민','전공 탐색','좋아하는 일'],experience:'동아리 포스터 제작, 동네 안내문 디자인 프로젝트',intro:'그림을 좋아하던 마음이 전공 선택으로 이어졌어요. 전공의 일상과 실패한 스케치도 함께 나눠요.'},
 b2:{school:'온길대학교 (가상)',department:'자유전공학부',year:'2학년',concerns:['전공 탐색','진로 고민'],experience:'도서관 봉사, 사진 동아리, 짧은 코딩 수업',intro:'아직 하나의 진로를 정하지 못했지만 작은 경험을 기록하며 선택의 기준을 찾고 있어요.'},
 b3:{school:'새봄대학교 (가상)',department:'컴퓨터공학과',year:'졸업',concerns:['프로젝트 시작','진로 고민'],experience:'동네 불편을 살피는 작은 개발 프로젝트',intro:'기술 자체보다 누구의 어떤 문제를 풀지 먼저 궁금해하는 개발자예요.'},
 b4:{school:'온길대학교 (가상)',department:'교육학과',year:'3학년',concerns:['공부 방법','대학 생활'],experience:'학습 기록과 나에게 맞는 공부 루틴 탐색',intro:'누구에게나 맞는 정답보다 각자의 속도를 찾는 경험을 이야기해요.'},
 b5:{school:'다온대학교 (가상)',department:'지역개발학과',year:'졸업',concerns:['프로젝트 시작','대학 생활'],experience:'지역 청년 모임과 동네 행사 기획',intro:'내가 사는 곳에서 작은 일을 시작하며 만난 사람들과 시행착오를 나눠요.'},
 b6:{school:'다온대학교 (가상)',department:'융합과학과',year:'2학년',concerns:['전공 탐색','좋아하는 일'],experience:'과학 탐구와 음악 등 여러 관심사를 연결한 활동',intro:'관심사가 많아도 괜찮아요. 여러 질문이 만나는 지점을 함께 찾아보고 싶어요.'}
};
const concernOptions=['진로 고민','전공 탐색','공부 방법','대학 생활','프로젝트 시작','좋아하는 일'];
let mentorCriteria={school:'전체',department:'전체',concern:'전체'},communityTab='questions',boardQuery='',boardConcern='전체',chatSender='mentee';
function seedQuestions(){return [
 {id:'q-demo-1',title:'전공을 정하지 못했을 때 어떤 활동부터 해보면 좋을까요?',body:'아직 관심 있는 분야가 뚜렷하지 않아요. 큰 준비 없이 해볼 수 있는 작은 경험이 궁금해요.',concern:'전공 탐색',author:'잎새 · 가상 인물',example:true,answers:[{id:'a-demo-1',body:'저는 짧은 수업과 동아리를 하나씩 경험하고 좋았던 순간을 적어봤어요. 이번 주에 해볼 작은 실험 하나부터 골라보면 어떨까요?',author:'도현',bookId:'b2',example:true}],created:null},
 {id:'q-demo-2',title:'처음 만드는 프로젝트는 얼마나 작게 시작해도 될까요?',body:'개발에 관심은 있지만 대단한 결과물을 만들어야 할 것 같아 망설여져요.',concern:'프로젝트 시작',author:'새싹 · 가상 인물',example:true,answers:[],created:null}
]}
function mentorInfo(b){return b.id.startsWith('own')?(b.mentorProfile||state.account?.profile||{}):(mentorExamples[b.id]||{})}
function mentorMatches(b){const p=mentorInfo(b);return (mentorCriteria.school==='전체'||p.school===mentorCriteria.school)&&(mentorCriteria.department==='전체'||p.department===mentorCriteria.department)&&(mentorCriteria.concern==='전체'||(p.concerns||[]).includes(mentorCriteria.concern))}
function mentorFilters(){const list=allBooks().filter(b=>!state.blocked.includes(b.id)),schools=[...new Set(list.map(b=>mentorInfo(b).school).filter(Boolean))],departments=[...new Set(list.map(b=>mentorInfo(b).department).filter(Boolean))];return `<details class="mentor-filter-box" ${Object.values(mentorCriteria).some(v=>v!=='전체')?'open':''}><summary>${icon('search')}학교·학과·고민으로 찾기 <span>세부 필터</span></summary><div class="mentor-filter-fields">${[['school','학교',schools],['department','학과',departments],['concern','고민 유형',concernOptions]].map(([key,label,options])=>`<label class="field"><span>${label}</span><select data-mentor-filter="${key}" aria-label="멘토 ${label} 필터"><option value="전체">전체 ${label}</option>${options.map(v=>`<option ${mentorCriteria[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}<button class="btn" data-action="reset-mentor-filters">필터 초기화</button></div><p>예시 멘토의 학교·학과는 모두 가상 정보예요. 결과에서 책을 읽고 직접 대화를 신청할 수 있어요.</p></details>`}
function mentorProfilePanel(b){const p=mentorInfo(b);return `<section class="mentor-profile-panel"><header><div class="eyebrow">MEET THE STORYTELLER</div><h3>이야기 뒤의 사람</h3><span class="simulation-label">${b.id.startsWith('own')?'내 체험 프로필 · 실제 확인 전':'가상 멘토 프로필 · 실제 확인 전'}</span></header><dl><div><dt>학교</dt><dd>${esc(p.school||'미등록')}</dd></div><div><dt>학과</dt><dd>${esc(p.department||'미등록')}</dd></div><div><dt>학년</dt><dd>${esc(p.year||'미등록')}</dd></div><div><dt>관심 분야</dt><dd>${esc(p.interests||classificationsOf(b).map(c=>c.name).join(' · '))}</dd></div></dl><p class="mentor-intro-text">${esc(p.intro||b.affiliation)}</p><h4>함께 나눌 경험</h4><p>${esc(p.experience||b.help)}</p><div class="tags">${(p.concerns||[]).map(c=>`<span># ${esc(c)}</span>`).join('')}</div></section>`}
function memberAccess(){return `<button class="member-access" data-action="account" aria-label="${state.account?'내 체험 프로필':'회원가입 및 학생 인증'}">${icon('user')}<span>${state.account?esc(state.account.nickname):'회원가입·인증'}</span></button>`}
function requireMember(){if(state.account)return true;accountPageModal();toast('먼저 별명으로 회원가입을 체험해주세요.');return false}
function accountPageModal(){closeModal();if(page==='account')render();else location.hash='account'}
function accountPage(){const a=state.account;return `<div class="page-heading"><div class="eyebrow">MY LIBRARY ID</div><h1>나의 작은 도서관 회원증.</h1><p>별명으로 시작하고, 학생 인증 과정을 체험해요.</p></div><div class="membership-layout"><section class="library-id"><div class="eyebrow">WONJU HUMAN STORY LIBRARY</div>${icon('user')}<h2>${a?esc(a.nickname):'나의 첫 회원증'}</h2><p>${a?(a.role==='mentor'?'이야기를 나누는 멘토':'이야기를 읽는 멘티'):'아직 가입 전이에요'}</p><span class="id-verification">${a?.verification?'학생 인증 체험 완료':'학생 인증 전'}</span><small>PROTOTYPE · 실제 신원 확인 아님</small><div class="id-bars" aria-hidden="true"></div></section><section class="panel"><h2>${a?'내 프로필':'회원가입 체험'}</h2><p>실명·비밀번호·실제 연락처는 수집하지 않아요. 이 브라우저에서 쓸 별명을 정해주세요.</p><form id="member-form"><label class="field"><span>나의 별명</span><input name="nickname" required maxlength="16" value="${esc(a?.nickname||'')}" placeholder="예: 초록"></label><label class="field"><span>참여 역할</span><select name="role"><option value="mentee" ${a?.role!=='mentor'?'selected':''}>멘티 · 이야기를 읽어요</option><option value="mentor" ${a?.role==='mentor'?'selected':''}>멘토 · 경험을 나눠요</option></select></label><label class="checkline"><input type="checkbox" name="demoConsent" required ${a?'checked':''}><span>가상 데이터로 체험하며 실제 개인정보는 입력하지 않을게요.</span></label><button class="btn primary" type="submit">${a?'프로필 저장':'회원가입 체험 시작'}</button></form></section></div>${a?`<section class="panel verification-panel"><div><div class="eyebrow">STUDENT VERIFICATION</div><h2>학생 인증</h2><p>${a.verification?`${a.verification.method==='email'?'학교 이메일':'재학 정보'} 방식의 인증 절차를 체험했어요. 실제 재학·소속 확인과 멘토 승인은 별도예요.`:'학교 이메일 또는 재학 정보 확인 방식을 골라보세요.'}</p></div><div class="actions"><button class="btn primary" data-action="verify-student" data-value="email">학교 이메일 인증 체험</button><button class="btn" data-action="verify-student" data-value="enrollment">재학 정보 확인 체험</button></div><small>인증 메일 발송이나 재학 서류 검증은 연결하지 않았어요. 실제 이메일·증명서는 입력하거나 업로드하지 않아요.</small></section><section class="panel"><div class="eyebrow">MY MENTOR PROFILE</div><h2>나의 멘토 소개</h2><p>스펙보다 함께 나눌 수 있는 경험을 담아요. 실제 소속 확인 전인 체험용 소개입니다.</p>${mentorProfileForm(a.profile||{})}</section>`:''}<div class="account-shortcuts"><a class="btn" href="#library">${icon('library')} 책 둘러보기</a><a class="btn" href="#shelf">${icon('bookmark')} 나의 책장</a><a class="btn" href="#studio">${icon('pen')} 나의 책 쓰기</a><a class="btn" href="#meetings">${icon('calendar')} 만남·후기 기록</a></div>`}
function mentorProfileForm(p){return `<form id="mentor-profile-form"><div class="form-grid"><label class="field"><span>학교 · 체험용</span><select name="school" required><option value="">학교를 골라주세요</option>${['새봄대학교 (가상)','온길대학교 (가상)','다온대학교 (가상)','가상 고등학교','학교 소속 없음'].map(v=>`<option ${p.school===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>학과 · 체험용</span><input name="department" maxlength="35" required value="${esc(p.department||'')}" placeholder="예: 시각디자인학과"></label><label class="field"><span>학년</span><select name="year">${['1학년','2학년','3학년','4학년','대학원','졸업','해당 없음'].map(v=>`<option ${p.year===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>관심 분야</span><select name="interests">${categories.slice(1).map(v=>`<option ${p.interests===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div><fieldset class="concern-options"><legend>함께 이야기할 고민</legend>${concernOptions.map(v=>`<label><input type="checkbox" name="concerns" value="${v}" ${(p.concerns||[]).includes(v)?'checked':''}>${v}</label>`).join('')}</fieldset><label class="field"><span>나누고 싶은 경험</span><textarea name="experience" required maxlength="600" placeholder="작은 프로젝트나 시행착오도 좋아요.">${esc(p.experience||'')}</textarea></label><label class="field"><span>나를 소개하는 글</span><textarea name="intro" required maxlength="600">${esc(p.intro||'')}</textarea></label><p class="form-error" id="profile-error" role="alert"></p><button class="btn primary" type="submit">멘토 소개 저장</button></form>`}
function studentVerification(method){if(!requireMember())return;const email=method==='email';openModal(email?'학교 이메일 인증 체험':'재학 정보 확인 체험',`<form id="verification-form" class="modal-body" data-method="${method}"><div class="eyebrow">VERIFICATION DEMO</div><h3>${email?'이메일로 학생 인증하기':'재학 정보로 학생 인증하기'}</h3><p>실제 신원이나 재학 상태를 확인하지 않는 모의 절차예요.</p>${email?`<label class="field"><span>체험용 학교 이메일</span><input type="email" value="leaf@campus.example" readonly></label><button class="btn soft" type="button" data-action="send-verification">인증번호 받기 · 모의 발송</button><p id="verification-code-hint" class="pill-note" role="status">메일은 전송되지 않아요. 위 버튼으로 체험용 번호를 확인해요.</p><label class="field"><span>인증번호 6자리</span><input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off" placeholder="체험용 인증번호 입력"></label>`:`<label class="field"><span>학교 · 예시</span><select name="school" required><option value="">선택해주세요</option><option>새봄대학교 (가상)</option><option>온길대학교 (가상)</option><option>다온대학교 (가상)</option><option>가상 고등학교</option></select></label><label class="field"><span>학년</span><select name="year"><option>1학년</option><option>2학년</option><option>3학년</option><option>4학년</option></select></label><label class="checkline"><input type="checkbox" name="enrollment" required><span>가상 재학 정보 확인 과정을 체험합니다. 실제 서류는 제출하지 않아요.</span></label>`}<p class="form-error" id="verification-error" role="alert"></p><button class="btn primary full" type="submit">학생 인증 완료 체험</button><div class="notice">이 표시가 실제 학생 인증이나 멘토 검증을 뜻하지 않아요. 가입·인증 상태는 이 브라우저에만 저장돼요.</div></form>`);}
function accountShelfLinks(){return `<div class="my-space-links"><button data-action="account">${icon('user')}<span>${state.account?esc(state.account.nickname)+'님의 회원증':'회원가입·학생 인증'}<small>내 프로필 관리</small></span>${icon('arrow')}</button><a href="#studio">${icon('pen')}<span>나의 책 쓰기<small>내 경험을 한 권으로</small></span>${icon('arrow')}</a></div>`}
function hasContact(text){return /(?:[\w.+-]+@[\w.-]+\.[a-z]{2,}|01[016789][\s.-]?\d{3,4}[\s.-]?\d{4}|https?:\/\/\S+)/i.test(text)}
function questionsVisible(){return state.questions.filter(q=>!state.hiddenQuestions.includes(q.id))}
function communityPage(){return `<div class="page-heading"><div class="eyebrow">QUESTIONS OPEN NEW CHAPTERS</div><h1>작은 질문에서,<br>다음 이야기가 시작돼요.</h1><p>함께 궁금해하고, 앱 안에서 안전하게 대화해요.</p></div><div class="community-heading"><div class="segmented" aria-label="질문과 대화"><button data-action="community-tab" data-value="questions" class="${communityTab==='questions'?'active':''}" aria-pressed="${communityTab==='questions'}">공개 질문</button><button data-action="community-tab" data-value="chats" class="${communityTab==='chats'?'active':''}" aria-pressed="${communityTab==='chats'}">1:1 대화 ${state.conversations.filter(c=>!state.blocked.includes(c.bookId)).length||''}</button></div>${communityTab==='questions'?'<button class="btn primary" data-action="ask-question">'+icon('pen')+' 질문 남기기</button>':''}</div><div class="notice compact">모든 글·대화는 이 브라우저의 체험 기록이에요. 실제 이용자에게 전달되지 않아요. 연락처·학교 실명·민감한 정보는 적지 마세요.</div>${communityTab==='questions'?questionBoard():conversationList()}`}
function questionBoard(){const list=questionsVisible().filter(q=>(boardConcern==='전체'||q.concern===boardConcern)&&(!boardQuery||[q.title,q.body].join(' ').toLowerCase().includes(boardQuery.toLowerCase())));return `<form id="board-search-form" class="board-tools"><label class="search">${icon('search')}<input name="query" aria-label="공개 질문 검색" placeholder="함께 궁금한 질문을 찾아보세요" value="${esc(boardQuery)}"><button aria-label="질문 검색" type="submit">${icon('arrow')}</button></label><label class="field"><span class="sr-only">질문 고민 유형</span><select name="concern" aria-label="질문 고민 유형"><option value="전체">모든 고민</option>${concernOptions.map(v=>`<option ${boardConcern===v?'selected':''}>${v}</option>`).join('')}</select></label><button class="btn" type="submit">검색</button></form><div class="result-meta"><span>함께 나누는 질문 <strong>${list.length}</strong>개</span><span>개인정보 없이 편하게</span></div><div class="question-list">${list.map(q=>`<button class="question-card" data-action="open-question" data-id="${q.id}"><span class="question-tag">${esc(q.concern)}<small>${q.example?'예시 질문':'내 체험 질문'}</small></span><h2>${esc(q.title)}</h2><p>${esc(q.body)}</p><footer><span>${esc(q.author)}</span><span>답변 ${(q.answers||[]).length} ${icon('arrow')}</span></footer></button>`).join('')||'<div class="empty"><h3>아직 이 고민의 질문이 없어요.</h3><p>다른 단어로 검색하거나 첫 질문을 남겨보세요.</p></div>'}</div>`}
function askQuestion(){if(!requireMember())return;openModal('공개 질문 남기기',`<form id="question-form" class="modal-body"><div class="eyebrow">A SMALL QUESTION</div><h3>지금 무엇이 궁금한가요?</h3><label class="field"><span>고민 유형</span><select name="concern">${concernOptions.map(v=>`<option>${v}</option>`).join('')}</select></label><label class="field"><span>질문 제목</span><input name="title" required maxlength="80" placeholder="함께 생각해보고 싶은 질문"></label><label class="field"><span>질문 내용</span><textarea name="body" required maxlength="1500" placeholder="실제 개인정보 없이 체험용 내용을 적어주세요."></textarea></label><p class="form-error" id="question-error" role="alert"></p><div class="notice">공개 게시판에 글을 남기는 체험이에요. 다른 기기나 실제 이용자에게는 보이지 않아요.</div><button class="btn primary full" type="submit">질문 등록 체험</button></form>`)}
function questionDetail(id){const q=questionsVisible().find(x=>x.id===id);if(!q)return;openModal('함께 나누는 질문',`<div class="modal-body"><span class="question-tag">${esc(q.concern)} · ${q.example?'예시 질문':'내 체험 질문'}</span><h3 class="question-title">${esc(q.title)}</h3><p class="pill-note">${esc(q.author)}</p><p class="discussion-body">${esc(q.body)}</p><h4 class="answer-heading">함께 남긴 답변 ${(q.answers||[]).length}개</h4><div class="answer-list">${(q.answers||[]).map(a=>`<article class="answer-card"><header>${a.bookId?`<img src="${personPhotos[a.bookId]}" alt="가상 멘토 ${esc(a.author)}" width="32" height="32">`:icon('user')}<strong>${esc(a.author)}</strong><small>${a.example?'예시 답변':a.role==='mentor'?'멘토 역할 체험':'답변 체험'}</small></header><p class="discussion-body">${esc(a.body)}</p>${a.bookId?`<button class="text-link" data-action="read" data-id="${a.bookId}">이 멘토의 책 읽기 ${icon('arrow')}</button>`:''}</article>`).join('')||'<p class="pill-note">아직 답변이 없어요. 내 경험에서 한 줄을 나눠볼까요?</p>'}</div><form id="answer-form" data-question="${q.id}"><label class="field"><span>나의 답변</span><textarea name="body" required maxlength="1200" placeholder="한 사람의 경험으로 나눠주세요. 실제 개인정보는 적지 않아요."></textarea></label><label class="field"><span>답변 역할 · 체험</span><select name="role"><option value="mentee">멘티로 답변</option><option value="mentor">멘토 역할로 답변 체험</option></select></label><p id="answer-error" class="form-error" role="alert"></p><div class="actions"><button class="btn primary" type="submit">답변 남기기 체험</button><button type="button" class="btn" data-action="report-question" data-id="${q.id}">신고·숨기기</button></div></form></div>`,true)}
function reportQuestion(id){openModal('질문 신고·숨기기',`<form id="question-report-form" class="modal-body" data-question="${id}"><h3>불편한 내용을 알려주세요.</h3><p>실제 담당자에게 전달되지 않는 신고 체험이에요.</p><label class="field"><span>신고 이유</span><select name="reason"><option>부적절한 내용·답변</option><option>개인 연락·외부 만남 유도</option><option>허위 정보·상업적 권유</option></select></label><label class="checkline"><input type="checkbox" name="hide" checked><span>이 질문을 내 게시판에서 숨길게요.</span></label><button class="btn primary full" type="submit">신고 기록 체험</button></form>`)}
function conversationList(){const list=state.conversations.filter(c=>!state.blocked.includes(c.bookId)&&getBook(c.bookId));return `<div class="conversation-list">${list.map(c=>{const b=getBook(c.bookId),last=c.messages.at(-1);return `<button class="conversation-card" data-action="open-chat" data-id="${c.id}"><img src="${personPhotos[b.id]}" alt="${esc(b.name)}의 가상 사진"><span><strong>${esc(b.name)}님과 1:1 대화</strong><span>${esc(last?.body||'첫 질문을 남겨보세요.')}</span><small>체험 대화 · 실제 전송 안 됨</small></span>${icon('arrow')}</button>`}).join('')||empty('book','아직 시작한 대화가 없어요','책을 읽고 ‘1:1 대화’에서 궁금한 점을 남겨보세요.','사람책 둘러보기','library')}</div>`}
function startChat(bookId){if(!requireMember())return;const b=getBook(bookId);if(!b||state.blocked.includes(bookId)){toast('대화할 수 없는 사람책이에요.');return}if(bookId.startsWith('own')){toast('내 책에는 대화를 신청할 수 없어요.');return}let c=state.conversations.find(x=>x.bookId===bookId);if(!c){c={id:'chat-'+Date.now(),bookId,messages:[],created:Date.now()};state.conversations.unshift(c);persist()}chatDetail(c.id)}
function chatDetail(id){const c=state.conversations.find(x=>x.id===id);if(!c||!requireMember())return;const b=getBook(c.bookId);if(!b||state.blocked.includes(b.id)){toast('숨긴 사람책과의 대화는 열 수 없어요.');return}openModal(`${b.name}님과 1:1 대화 · 체험`,`<div class="modal-body chat-dialog"><div class="chat-person"><img src="${personPhotos[b.id]}" alt="${esc(b.name)}의 가상 사진"><div><h3>${esc(b.name)}</h3><span>${esc(mentorInfo(b).department||b.category)} · 가상 멘토</span></div><button class="btn" data-action="read" data-id="${b.id}">책 보기</button></div><div class="notice compact">실제 대화 상대는 연결되지 않았어요. 멘티·멘토 역할을 바꿔 메시지 흐름을 체험할 수 있어요. 외부 연락처와 만남은 공유하지 않아요.</div><div class="chat-messages" aria-label="체험 대화 기록">${c.messages.map(m=>`<div class="chat-bubble ${m.role==='mentor'?'mentor':'mine'}"><small>${m.role==='mentor'?esc(b.name)+' · 멘토 역할 체험':esc(state.account.nickname)+' · 내 체험 메시지'}</small><p>${esc(m.body)}</p></div>`).join('')||'<p class="chat-empty">책에서 궁금했던 점을 한 줄 남겨보세요.</p>'}</div><form id="chat-form" data-chat="${c.id}"><label class="field"><span>작성 역할 · 체험</span><select name="sender"><option value="mentee" ${chatSender==='mentee'?'selected':''}>멘티로 보내기</option><option value="mentor" ${chatSender==='mentor'?'selected':''}>멘토로 답장 체험</option></select></label><label class="field"><span>메시지</span><textarea name="body" maxlength="1500" required placeholder="실제 개인정보 없이 앱 안에서 질문을 나눠요."></textarea></label><p id="chat-error" class="form-error" role="alert"></p><div class="actions"><button class="btn primary" type="submit">메시지 보내기 체험 ${icon('arrow')}</button><button type="button" class="btn" data-action="report" data-id="${b.id}">신고·숨기기</button><button type="button" class="btn" data-action="open-conversations">대화 목록</button></div></form></div>`,true)}
function reviewFor(m){return state.reviews.find(r=>r.meetingId===m.id)}
function reviewSummary(m){const r=reviewFor(m);return r?`<div class="meeting-review"><strong>나의 만남 기록 · 만족도 ${r.rating}/5</strong><p><b>상담 요약</b>${esc(r.summary)}</p><p><b>다음 목표</b>${esc(r.nextGoal)}</p><small>${r.publicConsent&&r.publicNote?'별도로 작성한 공개 후기만 서가에 표시돼요.':'나의 기록으로 보관 중 · 서가에 표시하지 않아요.'}</small></div>`:''}
function reviewForm(id){const m=state.meetings.find(x=>x.id===id);if(!m||m.status!=='completed'){toast('완료한 만남에만 후기와 기록을 남길 수 있어요.');return}const r=reviewFor(m)||{};openModal('멘토링 후기와 나의 기록',`<form id="review-form" class="modal-body" data-meeting="${id}"><div class="eyebrow">AFTER OUR CONVERSATION</div><h3>${esc(getBook(m.bookId)?.name||'멘토')}님과의 대화를 돌아봐요.</h3><fieldset class="rating-options"><legend>만족도 평가</legend>${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" required ${Number(r.rating)===n?'checked':''}><span>${n} <span aria-hidden="true">★</span></span></label>`).join('')}</fieldset><label class="field"><span>상담 요약 · 나의 기록</span><textarea name="summary" required maxlength="1200" placeholder="오늘 얻은 힌트나 기억하고 싶은 이야기를 적어보세요.">${esc(r.summary||'')}</textarea></label><label class="field"><span>다음 목표 · 나의 기록</span><textarea name="nextGoal" required maxlength="400" placeholder="다음 만남 전 해보고 싶은 작은 시도 하나">${esc(r.nextGoal||'')}</textarea></label><div class="notice">상담 요약과 다음 목표는 개인 기록이에요. 아래 공개 후기는 따로 작성하고 동의한 경우에만 이 브라우저의 책 화면에 표시돼요.</div><label class="field"><span>책에 남길 공개 후기 <small>선택 · 실제 개인정보는 적지 마세요.</small></span><textarea name="publicNote" maxlength="300" placeholder="다른 독자에게 전하고 싶은 한 줄">${esc(r.publicNote||'')}</textarea></label><label class="checkline"><input type="checkbox" name="publicConsent" ${r.publicConsent?'checked':''}><span>만족도와 위에 따로 작성한 공개 후기를 책에 표시하는 체험에 동의해요.</span></label><p id="review-error" class="form-error" role="alert"></p><button class="btn primary full" type="submit">후기·기록 저장</button></form>`,true)}
function publicReviews(bookId){return state.reviews.filter(r=>r.publicConsent&&r.publicNote&&state.meetings.some(m=>m.id===r.meetingId&&m.bookId===bookId&&m.status==='completed'))}
function readerReviews(bookId){const list=publicReviews(bookId);return `<section class="reader-reviews"><div class="eyebrow">READERS’ NOTES</div><h3>이야기 뒤에 남긴 한 줄</h3>${list.length?list.map(r=>`<article><strong>${esc(r.author||'독자')} · 만족도 ${r.rating}/5</strong><p>${esc(r.publicNote)}</p><small>이 브라우저에서 작성한 공개 후기 체험</small></article>`).join(''):'<p>아직 남겨진 공개 후기가 없어요. 만남을 마치면 ‘나의 만남’에서 후기를 남길 수 있어요.</p>'}</section>`}
function submitMemberFeature(form){
 if(!form.reportValidity())return;const d=new FormData(form),text=name=>String(d.get(name)||'').trim(),contactError=(value,selector)=>{if(!hasContact(value))return false;$(selector).textContent='연락처·외부 링크 대신 앱 안에서 나눌 내용을 적어주세요.';return true};
 if(form.id==='member-form'){const nickname=text('nickname');if(!nickname){toast('사용할 별명을 적어주세요.');return}if(hasContact(nickname)){toast('연락처 대신 별명으로 입력해주세요.');return}state.account={...state.account,nickname,role:text('role'),profile:state.account?.profile||{},created:state.account?.created||Date.now()};state.role=state.account.role;persist();render();toast('체험용 회원증을 만들었어요. 실제 계정 가입은 아니에요.')}
 if(form.id==='verification-form'){if(!state.account)return;if(form.dataset.method==='email'&&(form.dataset.codeSent!=='yes'||text('code')!=='123456')){$('#verification-error').textContent='인증번호 받기를 누른 뒤 체험용 번호 123456을 입력해주세요.';return}state.account.verification={method:form.dataset.method,at:Date.now(),...(form.dataset.method==='enrollment'?{school:text('school'),year:text('year')}:{})};persist();closeModal();render();toast('학생 인증 절차를 체험했어요. 실제 재학 확인은 아니에요.')}
 if(form.id==='mentor-profile-form'){if(!state.account)return;if(contactError(text('experience')+' '+text('intro'),'#profile-error'))return;state.account.profile={school:text('school'),department:text('department'),year:text('year'),interests:text('interests'),experience:text('experience'),intro:text('intro'),concerns:d.getAll('concerns').map(String)};persist();render();toast('멘토 소개를 저장했어요. 내 사람책에도 함께 표시돼요.')}
 if(form.id==='board-search-form'){boardQuery=text('query');boardConcern=text('concern');render()}
 if(form.id==='question-form'){if(!requireMember())return;if(!text('title')||!text('body')){$('#question-error').textContent='질문 제목과 내용을 적어주세요.';return}if(contactError(text('title')+' '+text('body'),'#question-error'))return;const q={id:'q-'+Date.now(),title:text('title'),body:text('body'),concern:text('concern'),author:state.account.nickname,example:false,answers:[],created:Date.now()};state.questions.unshift(q);persist();render();questionDetail(q.id)}
 if(form.id==='answer-form'){if(!requireMember())return;const q=questionsVisible().find(x=>x.id===form.dataset.question);if(!q)return;if(!text('body'))return;if(contactError(text('body'),'#answer-error'))return;q.answers.push({id:'a-'+Date.now(),body:text('body'),author:state.account.nickname,role:text('role'),example:false});persist();render();questionDetail(q.id)}
 if(form.id==='question-report-form'){state.reports.push({kind:'question',questionId:form.dataset.question,reason:text('reason'),at:Date.now()});if(d.get('hide'))state.hiddenQuestions=[...new Set([...state.hiddenQuestions,form.dataset.question])];persist();closeModal();render();toast('질문 신고를 체험 기록에 저장했어요. 실제 전달은 없어요.')}
 if(form.id==='chat-form'){if(!state.account)return;const c=state.conversations.find(x=>x.id===form.dataset.chat);if(!c||state.blocked.includes(c.bookId))return;if(!text('body'))return;if(contactError(text('body'),'#chat-error'))return;chatSender=text('sender');c.messages.push({body:text('body'),role:chatSender,at:Date.now()});persist();render();chatDetail(c.id)}
 if(form.id==='review-form'){const m=state.meetings.find(x=>x.id===form.dataset.meeting);if(!m||m.status!=='completed')return;if(!text('summary')||!text('nextGoal')){$('#review-error').textContent='상담 요약과 다음 목표를 적어주세요.';return}if(contactError(text('summary')+' '+text('nextGoal')+' '+text('publicNote'),'#review-error'))return;if(d.get('publicConsent')&&!text('publicNote')){$('#review-error').textContent='공개할 후기를 한 줄 적거나 공개 동의를 해제해주세요.';return}const rating=Number(d.get('rating'));if(![1,2,3,4,5].includes(rating))return;const r={meetingId:m.id,rating,summary:text('summary'),nextGoal:text('nextGoal'),publicNote:text('publicNote'),publicConsent:!!d.get('publicConsent'),author:state.account?.nickname||'체험 독자',updated:Date.now()};state.reviews=state.reviews.filter(x=>x.meetingId!==m.id);state.reviews.push(r);persist();closeModal();render();toast('후기와 다음 목표를 저장했어요.')}
}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const {action,id,value}=b.dataset;switch(action){
 case 'account':accountPageModal();break;
 case 'verify-student':studentVerification(value);break;
 case 'send-verification':$('#verification-form').dataset.codeSent='yes';$('#verification-code-hint').textContent='모의 발송 완료 · 체험용 인증번호: 123456 (실제 메일 발송 없음)';break;
 case 'reset-mentor-filters':mentorCriteria={school:'전체',department:'전체',concern:'전체'};render();break;
 case 'community-tab':communityTab=value;render();break;
 case 'ask-question':askQuestion();break;
 case 'open-question':questionDetail(id);break;
 case 'report-question':reportQuestion(id);break;
 case 'start-chat':startChat(id);break;
 case 'open-chat':chatDetail(id);break;
 case 'open-conversations':communityTab='chats';closeModal();if(page==='community')render();else location.hash='community';break;
 case 'review':reviewForm(id);break;
 }});
document.addEventListener('change',event=>{if(!event.target.matches('[data-mentor-filter]'))return;mentorCriteria[event.target.dataset.mentorFilter]=event.target.value;$('#results').innerHTML=libraryResults()});
document.addEventListener('submit',event=>{if(!['member-form','verification-form','mentor-profile-form','board-search-form','question-form','answer-form','question-report-form','chat-form','review-form'].includes(event.target.id))return;event.preventDefault();submitMemberFeature(event.target)});
